// Generate arbitrary binary input; FUZZ_PARAM_STR() yields 1..4096 bytes
std::string raw = FUZZ_PARAM_STR();
// Maintain lifetime of the referenced data while std::string_view is used
std::string_view in(raw.data(), raw.size());

// Call the target function under test
std::string b64;
try {
    b64 = tfs::base64::encode(in);
} catch (...) {
    // Any exception from the API is treated as an error path for the fuzzer
    FUZZ_BAIL();
}

// Optional cross-check to increase coverage: decode(encode(x)) must equal x
try {
    std::string back = tfs::base64::decode(std::string_view(b64.data(), b64.size()));
    // Property-based assertion: round-trip of encode then decode must reproduce input
    FUZZ_ASSERT(back == raw, "base64 round-trip mismatch for encode->decode");
} catch (...) {
    // decode must not fail on encoder output
    FUZZ_BAIL();
}

// No persistent API-managed objects are produced; no outputs to return.
// Validation: The stub preserves input lifetime for string_view, handles exceptions, and asserts encode/decode round-trip correctness.

// Strategy: exercise both valid and arbitrary inputs to cover success and error-tolerance paths.
unsigned mode = *FUZZ_PARAM(unsigned int) % 2u;

if (mode == 0u) {
    // Valid path: create a guaranteed-valid Base64 string by encoding random bytes
    std::string raw = FUZZ_PARAM_STR();
    std::string b64;
    try {
        b64 = tfs::base64::encode(std::string_view(raw.data(), raw.size()));
    } catch (...) {
        FUZZ_BAIL();
    }

    // Decode the valid Base64 and assert round-trip
    try {
        std::string decoded = tfs::base64::decode(std::string_view(b64.data(), b64.size()));
        FUZZ_ASSERT(decoded == raw, "base64 round-trip mismatch for decode of encoder output");
    } catch (...) {
        FUZZ_BAIL();
    }
} else {
    // Arbitrary path: feed random text (may be invalid Base64) and ensure the call is safe
    std::string maybe_b64 = FUZZ_PARAM_STR();
    std::string out;
    try {
        out = tfs::base64::decode(std::string_view(maybe_b64.data(), maybe_b64.size()));
        // Do not assert on output content/size; behavior on invalid input is unspecified.
        // Optionally re-encode to exercise more code paths without imposing correctness constraints.
        (void)tfs::base64::encode(std::string_view(out.data(), out.size()));
    } catch (...) {
        // Treat exceptions as an error path rather than crashing the fuzzer
        FUZZ_BAIL();
    }
}

// No persistent API-managed objects are produced; no outputs to return.
// Validation: The stub keeps string_view valid, covers both valid/invalid input paths, and converts exceptions to fuzzer errors.

// Generate a plausible PEM string and call tfs::rsa::loadPEM.
// We enforce that the memory remains valid during the call and try to shape
// input toward realistic PEM to maximize successful parses.

// Choose a PEM label variant to cover multiple code paths
unsigned int variant = *FUZZ_PARAM(unsigned int) % 4;
const char *label = nullptr;
switch (variant) {
    case 0: label = "RSA PRIVATE KEY"; break;
    case 1: label = "PRIVATE KEY"; break;
    case 2: label = "PUBLIC KEY"; break;
    default: label = "RSA PUBLIC KEY"; break;
}

// Start from a fuzz string and filter it to base64 characters to look like PEM data
std::string raw = FUZZ_PARAM_STR();
// Cap size to keep within performance budget
if (raw.size() > 1500) raw.resize(1500);
std::string body; body.reserve(raw.size() + 64);
const char *b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
auto is_b64 = [&](char c){ for (const char *p=b64; *p; ++p) if (*p==c) return true; return false; };
for (char c : raw) {
    body.push_back(is_b64(c) ? c : 'A');
}
// Insert newlines every 64 chars as typical PEM formatting
std::string formatted;
formatted.reserve(body.size() + body.size()/64 + 64);
for (size_t i = 0; i < body.size(); ++i) {
    formatted.push_back(body[i]);
    if ((i % 64) == 63) formatted.push_back('\n');
}
if (formatted.empty()) formatted = "AA==\n"; // ensure non-empty body

// Assemble the final PEM text
std::string pem;
pem.reserve(formatted.size() + 64);
pem += "-----BEGIN "; pem += label; pem += "-----\n";
pem += formatted;
if (pem.back() != '\n') pem.push_back('\n');
pem += "-----END "; pem += label; pem += "-----\n";

// Call the target function
EVP_PKEY *pkey = tfs::rsa::loadPEM(std::string_view(pem));

// Validate: must return non-null on successful parse; otherwise bail to let the fuzzer try other inputs
if (!pkey) { FUZZ_BAIL(); }

// Attach attributes for downstream consumers
FUZZ_SET_ATTR_STR(pkey, "format", "PEM");
FUZZ_SET_ATTR_STR(pkey, "label", label);
FUZZ_SET_ATTR_INT_GLOBAL("tfs.rsa.key_loaded", 1);

// Output: pkey is returned to the object pool as a persistent handle

// Validation summary: Stub shapes random data into PEM-like input, checks for non-null return,
// and tags the resulting EVP_PKEY with attributes; memory lifetime of std::string_view is valid during the call.

// Use the provided 128-bit XTEA key (4x32-bit words). The runtime guarantees key != nullptr.
const xtea::key &kref = *key; // const-ref to satisfy API

// Expand once and persist the round keys as an owned object in the pool.
const xtea::round_keys rkv = xtea::expand_key(kref);

// Allocate a persistent round_keys object and copy the returned schedule into it.
xtea::round_keys *rk = new xtea::round_keys(rkv);

// Track provenance: this schedule was derived from this specific key pointer.
FUZZ_SET_ATTR_PTR(rk, "key_ptr", (void*)key);
FUZZ_SET_ATTR_INT(rk, "valid", 1);

// Validation: rk must be non-null and marked valid for downstream use in encrypt/decrypt.
FUZZ_ASSERT(rk != nullptr, "round_keys allocation failed");
// End stub: output rk back to the pool.
// Validation summary: Inputs respected (const-ref), outputs initialized and attributed for later checks.

// Require a valid precomputed round key schedule produced by expand_key.
if (FUZZ_GET_ATTR_INT(rk, "valid") != 1 || FUZZ_GET_ATTR_PTR(rk, "key_ptr") == nullptr) {
    // Not a known-good schedule; avoid invoking API with invalid parameters.
    FUZZ_BAIL();
}

// Generate an arbitrary buffer; constrain to a multiple of 8 bytes as required by XTEA.
std::string s = FUZZ_PARAM_STR();
size_t max_len = 1024; // keep allocations small for fuzzing performance
size_t n = s.size();
if (n > max_len) n = max_len;
// Adjust to block size (8 bytes); zero-length is allowed by the API.
n -= (n % 8);

if (n == 0) {
    // When length == 0, data may be null; this exercises the no-op path safely.
    xtea::encrypt(nullptr, 0, *rk);
} else {
    // Create a writable buffer and copy data in; in-place operation is performed by the API.
    std::vector<uint8_t> buf(n);
    if (n > 0) { std::memcpy(buf.data(), s.data(), n); }
    FUZZ_ASSERT(buf.data() != nullptr, "buffer must be non-null when length > 0");
    xtea::encrypt(reinterpret_cast<uint8_t*>(buf.data()), n, *rk);
}

// Keep rk alive; it is not consumed by encrypt.
FUZZ_ASSERT(rk != nullptr, "rk must remain valid after encrypt");
// Validation summary: Enforced block alignment, non-null data when n>0, and verified rk provenance.

// Require a valid precomputed round key schedule produced by expand_key.
if (FUZZ_GET_ATTR_INT(rk, "valid") != 1 || FUZZ_GET_ATTR_PTR(rk, "key_ptr") == nullptr) {
    FUZZ_BAIL();
}

// Generate a ciphertext buffer; ensure length is a multiple of 8 as required by XTEA.
std::string s = FUZZ_PARAM_STR();
size_t max_len = 1024; // cap for performance
size_t n = s.size();
if (n > max_len) n = max_len;
n -= (n % 8);

if (n == 0) {
    // Decrypt no-op path with null pointer permitted when length == 0.
    xtea::decrypt(nullptr, 0, *rk);
} else {
    // Writable buffer for in-place decryption.
    std::vector<uint8_t> buf(n);
    if (n > 0) { std::memcpy(buf.data(), s.data(), n); }
    FUZZ_ASSERT(buf.data() != nullptr, "buffer must be non-null when length > 0");
    xtea::decrypt(reinterpret_cast<uint8_t*>(buf.data()), n, *rk);
}

// Keep rk alive and return it to the pool for reuse.
FUZZ_ASSERT(rk != nullptr, "rk must remain valid after decrypt");
// Validation summary: Checked rk provenance, enforced block alignment, and obeyed data pointer semantics.

// Expand the provided 128-bit XTEA key into round keys.
// The runtime guarantees key != nullptr and owned by this stub invocation.
const xtea::key &kref = *key; // const reference matches API requirement

// Compute the round key schedule using the API.
const xtea::round_keys computed = xtea::expand_key(kref);

// Persist the schedule as a heap object for reuse by encrypt/decrypt stubs.
xtea::round_keys *rk = new xtea::round_keys(computed);
FUZZ_ASSERT(rk != nullptr, "xtea::round_keys allocation failed");

// Track provenance for safety and later validation in consumers.
FUZZ_SET_ATTR_PTR(rk, "key_ptr", (void*)key);
FUZZ_SET_ATTR_INT(rk, "valid", 1);

// Validation summary: Uses official API to derive round keys from a provided key, allocates output, and records provenance.

// Construct a 128-bit XTEA key (4 x 32-bit words) and return it as a persistent object.
// Avoid FUZZ_PARAM(uint32_t[4]) due to type mismatch; pull four scalars instead.
uint32_t w0 = *FUZZ_PARAM(uint32_t);
uint32_t w1 = *FUZZ_PARAM(uint32_t);
uint32_t w2 = *FUZZ_PARAM(uint32_t);
uint32_t w3 = *FUZZ_PARAM(uint32_t);

// Allocate the key on the heap for persistence across fuzzer calls.
xtea::key *key = new xtea::key;
FUZZ_ASSERT(key != nullptr, "xtea::key allocation failed");

// Initialize the key with fuzzed values; std::array provides contiguous 4 elements.
(*key)[0] = w0;
(*key)[1] = w1;
(*key)[2] = w2;
(*key)[3] = w3;

// Mark attributes for downstream provenance/validation.
FUZZ_SET_ATTR_INT(key, "valid", 1);

// Validation summary: Allocates and initializes a 128-bit key with four fuzzed words and tags it valid.

