import random
import base64
import string
from typing import List

# Generates interesting Base64-encoded text inputs for tfs::base64::decode.
# The fuzzer stub uses FUZZ_PARAM_STR for inputs; our bytes will be used as the
# initial buffer for those strings. We therefore emit plausible Base64 strings
# that decode successfully, along with variants that exercise padding, lengths,
# and optional whitespace.

_B64_ALPHABET = string.ascii_uppercase + string.ascii_lowercase + string.digits + "+/"
_WS = ["\n", "\r", "\t", " "]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _make_valid_b64_from_raw(rng: random.Random, raw: bytes, with_whitespace: bool) -> str:
    # Use Python's base64 for correctness, then optionally inject whitespace and line breaks.
    b64 = base64.b64encode(raw).decode('ascii')
    if not with_whitespace or len(b64) == 0:
        return b64

    # Insert random whitespace at random positions, ensure not to break '=' padding too much
    s = list(b64)
    inserts = rng.randint(1, max(1, len(b64)//8))
    for _ in range(inserts):
        pos = rng.randint(0, len(s))
        s.insert(pos, rng.choice(_WS))
    # Optionally wrap lines at 64/76 like common encoders
    if rng.random() < 0.5 and len(s) > 76:
        width = rng.choice([64, 76])
        out = []
        col = 0
        for ch in s:
            out.append(ch)
            col += 1
            if col >= width and ch not in "\r\n":
                out.append("\n")
                col = 0
        s = out
    return ''.join(s)


def _make_edge_case_b64(rng: random.Random) -> str:
    # Construct canonical edge cases that should decode successfully
    choice = rng.randint(0, 8)
    if choice == 0:
        return ""  # empty input
    if choice == 1:
        # Single quantum (3 bytes -> 4 chars)
        raw = _rand_bytes(rng, 3)
        return base64.b64encode(raw).decode('ascii')
    if choice == 2:
        # 1-byte input -> 2 data chars + '=='
        raw = _rand_bytes(rng, 1)
        return base64.b64encode(raw).decode('ascii')
    if choice == 3:
        # 2-byte input -> 3 data chars + '='
        raw = _rand_bytes(rng, 2)
        return base64.b64encode(raw).decode('ascii')
    if choice == 4:
        # Large input that stays within size cap when b64-encoded
        n = rng.randint(512, 1200)
        raw = _rand_bytes(rng, n)
        return base64.b64encode(raw).decode('ascii')
    if choice == 5:
        # With whitespace sprinkled
        raw = _rand_bytes(rng, rng.randint(0, 256))
        return _make_valid_b64_from_raw(rng, raw, with_whitespace=True)
    if choice == 6:
        # Multiple concatenated blocks (valid when whitespace is allowed)
        parts: List[str] = []
        for _ in range(rng.randint(2, 6)):
            raw = _rand_bytes(rng, rng.randint(1, 64))
            parts.append(base64.b64encode(raw).decode('ascii'))
            if rng.random() < 0.7:
                parts.append(rng.choice(_WS))
        return ''.join(parts)
    if choice == 7:
        # Padding stress: construct strings that end with many '=' lines
        raw = _rand_bytes(rng, rng.randint(1, 33))
        s = base64.b64encode(raw).decode('ascii')
        # Insert line breaks near the end
        if len(s) > 8:
            s = s[:-8] + "\n" + s[-8:-4] + "\r\n" + s[-4:]
        return s
    # choice == 8
    # RFC4648 URL-safe alphabet sometimes tolerated; include as near-valid variant
    raw = _rand_bytes(rng, rng.randint(0, 128))
    std = base64.b64encode(raw).decode('ascii')
    urlish = std.replace('+', '-').replace('/', '_')
    if rng.random() < 0.5:
        urlish = urlish.rstrip('=')  # missing padding variant
    return urlish


def _make_random_valid_b64(rng: random.Random) -> str:
    # Create a valid base64 with varied sizes and optional whitespace
    size_choice = rng.random()
    if size_choice < 0.2:
        raw_len = rng.randint(0, 64)
    elif size_choice < 0.6:
        raw_len = rng.randint(65, 512)
    else:
        raw_len = rng.randint(513, 1500)
    raw = _rand_bytes(rng, raw_len)
    return _make_valid_b64_from_raw(rng, raw, with_whitespace=rng.random() < 0.5)


def _maybe_mix_valid_and_near_valid(rng: random.Random) -> str:
    # Compose inputs that alternate between valid chunks and near-valid chunks
    pieces: List[str] = []
    for _ in range(rng.randint(2, 8)):
        if rng.random() < 0.7:
            pieces.append(_make_random_valid_b64(rng))
        else:
            # Near-valid: correct alphabet but with dropped padding or added whitespace
            s = _make_random_valid_b64(rng)
            if rng.random() < 0.5:
                s = s.rstrip('=')
            if rng.random() < 0.5:
                s = ''.join((ch if rng.random() > 0.1 else rng.choice(_WS)) for ch in s)
            pieces.append(s)
        # Occasionally insert separators/whitespace
        if rng.random() < 0.5:
            pieces.append(rng.choice(_WS) * rng.randint(1, 3))
    return ''.join(pieces)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a strategy aimed at exploring different decoder behaviors.
    strat = rng.randint(0, 6)
    if strat == 0:
        s = _make_random_valid_b64(rng)
    elif strat == 1:
        s = _make_valid_b64_from_raw(rng, _rand_bytes(rng, rng.randint(0, 2048)), with_whitespace=True)
    elif strat == 2:
        s = _make_edge_case_b64(rng)
    elif strat == 3:
        s = _maybe_mix_valid_and_near_valid(rng)
    elif strat == 4:
        # Strict alphabet random but length multiple of 4 with reasonable padding
        length_quanta = rng.randint(0, 512)
        s_chars = []
        for _ in range(length_quanta):
            s_chars.extend(rng.choice(_B64_ALPHABET) for _ in range(4))
        # Add optional correct padding at the end
        pad_mode = rng.randint(0, 2)
        if pad_mode == 1 and len(s_chars) >= 2:
            s_chars[-1] = '='
        elif pad_mode == 2 and len(s_chars) >= 2:
            s_chars[-1] = '='
            s_chars[-2] = '='
        s = ''.join(s_chars)
    elif strat == 5:
        # URL-safe variant sometimes accepted by decoders
        raw = _rand_bytes(rng, rng.randint(0, 1024))
        s = base64.urlsafe_b64encode(raw).decode('ascii')
        if rng.random() < 0.5:
            s = s.rstrip('=')  # missing padding
    else:
        # Short random cases including empty and tiny inputs, with whitespace
        s = _make_valid_b64_from_raw(rng, _rand_bytes(rng, rng.randint(0, 32)), with_whitespace=rng.random() < 0.8)

    # Enforce output size limit
    b = s.encode('ascii', errors='ignore')[:4096]
    return b
